mapper.select:
SELECT J.*, U.USER_NM, (SELECT MAX(C.CNTN_BGNG_DT) FROM cntn_log C WHERE C.USER_ID = J.USER_ID AND C.CNTN_YN = 'Y' AND C.CNTN_BGNG_DT <= J.LOG_CRT_DT) AS LGN_DT FROM job_log J LEFT JOIN user_info U ON U.USER_ID = J.USER_ID WHERE 1 = 1 AND J.LOG_CRT_DT >= CONCAT(#{startDate}, ' 00:00:00') AND J.LOG_CRT_DT < DATE_ADD(#{endDate}, INTERVAL 1 DAY) AND J.CNTN_MENU_NM = #{cntnMenuNm} AND J.JOB_SE_CD = #{jobSeCd}
AND (J.USER_ID LIKE CONCAT('%', #{searchKeyword}, '%') OR U.USER_NM LIKE CONCAT('%', #{searchKeyword}, '%') OR J.USER_IP_ADDR LIKE CONCAT('%', #{searchKeyword}, '%') OR J.TRGT_KEY_VL LIKE CONCAT('%', #{searchKeyword}, '%'))
ORDER BY J.LOG_CRT_DT DESC, J.JOB_LOG_SN DESC LIMIT 500
